{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 9,
      "text_ar": "قَالَتْ لِي: اِتْرُكْنِي وَحْدِي يَا سَيِّدِي لأَبْكِيَ عَلَى نَفْسِي وَأَزِيدَ حُزْنِي، فَإِنِّي مُضْطَرِبَةُ الْبَالِ جِدّاً وَمُنْحَطَّةٌ إِلَى أَدْنَى مَحَطٍّ.",
      "verse": 41
    },
    {
      "chapter": 9,
      "text_ar": "فَقُلْتُ لَهَا: مَا بِكِ؟ أَخْبِرِينِي.",
      "verse": 42
    },
    {
      "chapter": 9,
      "text_ar": "فَقَالَتْ لِي: إِنِّي أَنَا خَادِمَتَكَ كُنْتُ عَاقِرًا بِلا وَلَدٍ وَلِي زَوْجٌ مُنْذُ ثَلاثِينَ سَنَةً.",
      "verse": 43
    },
    {
      "chapter": 9,
      "text_ar": "وَكُنْتُ كُلَّ سَاعَةٍ وَكُلَّ يَوْمٍ طِوَالَ هَذِهِ الثَّلاثِينَ سَنَةً أَرْفَعُ صَلَاتِي إِلَى الْعَلِيِّ لَيْلاً وَنَهَاراً.",
      "verse": 44
    },
    {
      "chapter": 9,
      "text_ar": "وَحَدَثَ بَعْدَ ثَلاثِينَ سَنَةً أَنَّ اللَّهَ سَمِعَنِي أَنَا أَمَتَكَ وَرَأَى مَسْكَنَتِي وَاعْتَبَرَ شَقَائِي وَأَعْطَانِي ابْناً فَفَرِحْتُ بِهِ كَثِيراً أَنَا وَزَوْجِي وَجَمِيعُ جِيرَانِي وَأَعْطَيْنَا مَجْداً عَظِيماً لِلْقَدِيرِ.",
      "verse": 45
    }
  ]
}
